import{_ as a,a0 as d,w as c,s as l,ao as r,I as s,x as t,a1 as o,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"RHCSA 系列（八）: 加固 SSH，設定主機名及啓用網絡服務 | LCTT x X-CMD","titleTemplate":false,"description":"RHCSA 系列（八）: 加固 SSH，設定主機名及啓用網絡服務 | LCTT (RHCSA Series) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"RHCSA 系列（八）: 加固 SSH，設定主機名及啓用網絡服務 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"RHCSA 系列（八）: 加固 SSH，設定主機名及啓用網絡服務 | LCTT (RHCSA Series) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RHCSA Series/RHCSA Series--Part 08--Securing SSH, Setting Hostname and Enabling Network Services","title":"RHCSA 系列（八）: 加固 SSH，設定主機名及啓用網絡服務","tag":"RHCSA Series","desc":""},"relativePath":"RHCSA Series/RHCSA Series--Part 08--Securing SSH, Setting Hostname and Enabling Network Services.md","filePath":"[post].md"}'),i={name:"RHCSA Series/RHCSA Series--Part 08--Securing SSH, Setting Hostname and Enabling Network Services.md"};function m(S,e,h,w,u,H){const n=d("Link");return c(),l("div",null,[e[17]||(e[17]=r(`<h1 id="rhcsa-系列-八-加固-ssh-設定主機名及啓用網絡服務" tabindex="-1">RHCSA 系列（八）: 加固 SSH，設定主機名及啓用網絡服務 <a class="header-anchor" href="#rhcsa-系列-八-加固-ssh-設定主機名及啓用網絡服務" aria-label="Permalink to “RHCSA 系列（八）: 加固 SSH，設定主機名及啓用網絡服務”">​</a></h1><p>作為一名系統管理員，你將經常使用一個終端模擬器來登錄到一個遠程的系統中，執行一系列的管理任務。你將很少有機會坐在一個真實的（物理）終端前，所以你需要設定好一種方法來使得你可以登錄到你需要去管理的那台遠程主機上。</p><p>事實上，當你必須坐在一台物理終端前的時候，就可能是你登錄到該主機的最後一種方法了。基於安全原因，使用 Telnet 來達到以上目的並不是一個好主意，因為穿行在線纜上的流量並沒有被加密，它們以明文方式在傳送。</p><p>另外，在這篇文章中，我們也將複習如何配置網絡服務來使得它在開機時被自動開啓，並學習如何設置網絡和靜態或動態地解析主機名。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Secure-SSH-Server-and-Enable-Network-Services.png" alt="RHCSA: 安全 SSH 和開啓網絡服務"></p><p><em>RHCSA: 安全 SSH 和開啓網絡服務 – Part 8</em></p><h3 id="安裝並確保-ssh-通信安全" tabindex="-1">安裝並確保 SSH 通信安全 <a class="header-anchor" href="#安裝並確保-ssh-通信安全" aria-label="Permalink to “安裝並確保 SSH 通信安全”">​</a></h3><p>對於你來説，要能夠使用 SSH 遠程登錄到一個 RHEL 7 機子，你必須安裝 <code>openssh</code>，<code>openssh-clients</code> 和 <code>openssh-servers</code> 軟件包。下面的命令不僅將安裝遠程登錄程序，也會安裝安全的文件傳輸工具以及遠程文件複製程序：</p><pre><code># yum update &amp;&amp; yum install openssh openssh-clients openssh-servers
</code></pre><p>注意，也安裝上服務器所需的相應軟件包是一個不錯的主意，因為或許在某個時刻，你想使用同一個機子來作為客户端和服務器。</p><p>在安裝完成後，如若你想安全地訪問你的 SSH 服務器，你還需要考慮一些基本的事情。下面的設定應該出現在文件 <code>/etc/ssh/sshd_config</code> 中。</p><p>1、 更改 sshd 守護進程的監聽端口，從 22（默認的端口值）改為一個更高的端口值（2000 或更大），但首先要確保所選的端口沒有被佔用。</p>`,12)),s("p",null,[e[1]||(e[1]=t("例如，讓我們假設你選擇了端口 2500 。使用 ",-1)),o(n,{href:"http://www.tecmint.com/20-netstat-commands-for-linux-network-management/"},{default:p(()=>[...e[0]||(e[0]=[t("netstat",-1)])]),_:1}),e[2]||(e[2]=t(" 來檢查所選的端口是否被佔用：",-1))]),e[18]||(e[18]=r(`<pre><code># netstat -npltu | grep 2500
</code></pre><p>假如 netstat 沒有返回任何信息，則你可以安全地為 sshd 使用端口 2500，並且你應該在上面的配置文件中更改端口的設定，具體如下：</p><pre><code>Port 2500
</code></pre><p>2、 只允許協議 2（LCTT 譯註：SSHv1 已經被證明不安全，默認情況下 SSHv1 和 SSHv2 都支持，所以應該顯示去掉如下配置行的註釋，並只支持 SSHv2。）：</p><pre><code>Protocol 2
</code></pre><p>3、 配置驗證超時的時間為 2 分鐘，不允許以 root 身份登錄，並將允許通過 ssh 登錄的人數限制到最小：</p><pre><code>LoginGraceTime 2m
PermitRootLogin no
AllowUsers gacanepa
</code></pre><p>4、 假如可能，使用基於公鑰的驗證方式而不是使用密碼：</p><pre><code>PasswordAuthentication no
RSAAuthentication yes
PubkeyAuthentication yes
</code></pre><p>這假設了你已經在你的客户端機子上創建了帶有你的用户名的一個密鑰對，並將公鑰複製到了你的服務器上。</p>`,10)),s("ul",null,[s("li",null,[o(n,{href:"https://linux.cn/article-5444-1.html"},{default:p(()=>[...e[3]||(e[3]=[t("開啓 SSH 無密碼登錄",-1)])]),_:1})])]),e[19]||(e[19]=r(`<h3 id="配置網絡和名稱的解析" tabindex="-1">配置網絡和名稱的解析 <a class="header-anchor" href="#配置網絡和名稱的解析" aria-label="Permalink to “配置網絡和名稱的解析”">​</a></h3><p>1、 每個系統管理員都應該對下面這個系統配置文件非常熟悉：</p><ul><li>/etc/hosts 被用來在小型網絡中解析“名稱” &lt;---&gt; “IP 地址”。</li></ul><p>文件 <code>/etc/hosts</code> 中的每一行擁有如下的結構：</p><pre><code>IP address - Hostname - FQDN
</code></pre><p>例如，</p><pre><code>192.168.0.10    laptop  laptop.gabrielcanepa.com.ar
</code></pre><p>2、 <code>/etc/resolv.conf</code> 特別指定 DNS 服務器的 IP 地址和搜索域，它被用來在沒有提供域名後綴時，將一個給定的查詢名稱對應為一個全稱域名。</p><p>在正常情況下，你不必編輯這個文件，因為它是由系統管理的。然而，若你非要改變 DNS 服務器的 IP 地址，建議你在該文件的每一行中，都應該遵循下面的結構：</p><pre><code>nameserver - IP address
</code></pre><p>例如，</p><pre><code>nameserver 8.8.8.8
</code></pre><p>3、 <code>/etc/host.conf</code> 特別指定在一個網絡中主機名被解析的方法和順序。換句話説，告訴名稱解析器使用哪個服務，並以什麼順序來使用。</p><p>儘管這個文件由幾個選項，但最為常見和基本的設置包含如下的一行：</p><pre><code>order bind,hosts
</code></pre><p>它意味着解析器應該首先查看 <code>resolv.conf</code> 中特別指定的域名服務器，然後到 <code>/etc/hosts</code> 文件中查找解析的名稱。</p><p>4、 <code>/etc/sysconfig/network</code> 包含了所有網絡接口的路由和全局主機信息。下面的值可能會被使用：</p><pre><code>NETWORKING=yes|no
HOSTNAME=value
</code></pre><p>其中的 value 應該是全稱域名（FQDN）。</p><pre><code>GATEWAY=XXX.XXX.XXX.XXX
</code></pre><p>其中的 XXX.XXX.XXX.XXX 是網關的 IP 地址。</p><pre><code>GATEWAYDEV=value
</code></pre><p>在一個帶有多個網卡的機器中， value 為網關設備名，例如 enp0s3。</p><p>5、 位於 <code>/etc/sysconfig/network-scripts</code> 中的文件（網絡適配器配置文件）。</p><p>在上面提到的目錄中，你將找到幾個被命名為如下格式的文本文件。</p><pre><code>ifcfg-name
</code></pre><p>其中 name 為網卡的名稱，由 <code>ip link show</code> 返回：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Check-IP-Address.png" alt="檢查網絡連接狀態"></p><p><em>檢查網絡連接狀態</em></p><p>例如：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Network-Files.png" alt="網絡文件"></p><p><em>網絡文件</em></p><p>除了環回接口（loopback），你還可以為你的網卡指定相似的配置。注意，假如設定了某些變量，它們將為這個指定的接口覆蓋掉 <code>/etc/sysconfig/network</code> 中定義的默認值。在這篇文章中，為了能夠解釋清楚，每行都被加上了註釋，但在實際的文件中，你應該避免加上註釋：</p><pre><code>HWADDR=08:00:27:4E:59:37 ### 網卡的 MAC 地址
TYPE=Ethernet ### 連接類型
BOOTPROTO=static ### 這代表着該網卡指定了一個靜態地址。
					  ### 如果這個值指定為 dhcp，這個網卡會從 DHCP 服務器獲取 IP 地址，並且就不應該出現以下兩行。
IPADDR=192.168.0.18
NETMASK=255.255.255.0
GATEWAY=192.168.0.1
NM_CONTROLLED=no ### 應該給以太網卡設置，以便可以讓 NetworkManager 可以修改這個文件。
NAME=enp0s3
UUID=14033805-98ef-4049-bc7b-d4bea76ed2eb
ONBOOT=yes ### 操作系統會在啓動時打開這個網卡。
</code></pre><h3 id="設定主機名" tabindex="-1">設定主機名 <a class="header-anchor" href="#設定主機名" aria-label="Permalink to “設定主機名”">​</a></h3><p>在 RHEL 7 中， <code>hostnamectl</code> 命令被同時用來查詢和設定系統的主機名。</p><p>要展示當前的主機名，輸入：</p><pre><code># hostnamectl status
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Check-System-hostname.png" alt="在RHEL 7 中檢查系統的主機名"></p><p><em>檢查系統的主機名</em></p><p>要更改主機名，使用</p><pre><code># hostnamectl set-hostname [new hostname]
</code></pre><p>例如，</p><pre><code># hostnamectl set-hostname cinderella
</code></pre><p>要想使得更改生效，你需要重啓 hostnamed 守護進程（這樣你就不必因為要應用更改而登出並再登錄系統）：</p><pre><code># systemctl restart systemd-hostnamed
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Set-System-Hostname.png" alt="在 RHEL7 中設定系統主機名"></p><p><em>設定系統主機名</em></p><p>另外， RHEL 7 還包含 <code>nmcli</code> 工具，它可被用來達到相同的目的。要展示主機名，運行：</p><pre><code># nmcli general hostname
</code></pre><p>且要改變主機名，則運行：</p><pre><code># nmcli general hostname [new hostname]
</code></pre><p>例如，</p><pre><code># nmcli general hostname rhel7
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/nmcli-command.png" alt="使用 nmcli 命令來設定主機名"></p><p><em>使用 nmcli 命令來設定主機名</em></p><h3 id="在開機時開啓網絡服務" tabindex="-1">在開機時開啓網絡服務 <a class="header-anchor" href="#在開機時開啓網絡服務" aria-label="Permalink to “在開機時開啓網絡服務”">​</a></h3><p>作為本文的最後部分，就讓我們看看如何確保網絡服務在開機時被自動開啓。簡單來説，這個可通過創建符號鏈接到某些由服務的配置文件中的 <code>[Install]</code> 小節中指定的文件來實現。</p><p>以 firewalld（/usr/lib/systemd/system/firewalld.service） 為例：</p><pre><code>[Install]
WantedBy=basic.target
Alias=dbus-org.fedoraproject.FirewallD1.service
</code></pre><p>要開啓該服務，運行：</p><pre><code># systemctl enable firewalld
</code></pre><p>另一方面，要禁用 firewalld，則需要移除符號鏈接：</p><pre><code># systemctl disable firewalld
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Enable-Service-at-System-Boot.png" alt="在開機時開啓服務"></p><p><em>在開機時開啓服務</em></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在這篇文章中，我們總結了如何安裝 SSH 及使用它安全地連接到一個 RHEL 服務器；如何改變主機名，並在最後如何確保在系統啓動時開啓服務。假如你注意到某個服務啓動失敗，你可以使用 <code>systemctl status -l [service]</code> 和 <code>journalctl -xn</code> 來進行排錯。</p><p>請隨意使用下面的評論框來讓我們知曉你對本文的看法。提問也同樣歡迎。我們期待着你的反饋！</p><hr>`,70)),s("p",null,[e[5]||(e[5]=t("via: ",-1)),o(n,{href:"http://www.tecmint.com/rhcsa-series-secure-ssh-set-hostname-enable-network-services-in-rhel-7/"},{default:p(()=>[...e[4]||(e[4]=[t("http://www.tecmint.com/rhcsa-series-secure-ssh-set-hostname-enable-network-services-in-rhel-7/",-1)])]),_:1})]),s("p",null,[e[9]||(e[9]=t("作者：",-1)),o(n,{href:"http://www.tecmint.com/author/gacanepa/"},{default:p(()=>[...e[6]||(e[6]=[t("Gabriel Cánepa",-1)])]),_:1}),e[10]||(e[10]=t(" 譯者：",-1)),o(n,{href:"https://github.com/FSSlc"},{default:p(()=>[...e[7]||(e[7]=[t("FSSlc",-1)])]),_:1}),e[11]||(e[11]=t(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:p(()=>[...e[8]||(e[8]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[14]||(e[14]=t("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[12]||(e[12]=[t("LCTT",-1)])]),_:1}),e[15]||(e[15]=t(" 原創翻譯，",-1)),o(n,{href:"https://linux.cn/"},{default:p(()=>[...e[13]||(e[13]=[t("Linux中國",-1)])]),_:1}),e[16]||(e[16]=t(" 榮譽推出",-1))])])}const A=a(i,[["render",m]]);export{f as __pageData,A as default};
